The planning layer determines what actions to take:

from enum import Enum
from typing import Optional

class RobotTask(Enum):
    IDLE = "idle"
    NAVIGATE = "navigate"
    MANIPULATE = "manipulate"
    EXPLORE = "explore"

class TaskPlanner:
    """High-level task planning for the robot."""

    def __init__(self, world_model: WorldModel):
        self.world_model = world_model
        self.current_task: Optional[RobotTask] = None

    def plan_next_action(self, goal: str) -> RobotTask:
        """Determine the next task based on the goal."""
        # Simple goal parsing (in practice, use LLM or planner)
        if "go to" in goal.lower():
            return RobotTask.NAVIGATE
        elif "pick up" in goal.lower():
            return RobotTask.MANIPULATE
        elif "explore" in goal.lower():
            return RobotTask.EXPLORE
        return RobotTask.IDLE

LiDAR (Light Detection and Ranging) uses laser pulses to measure precise distances:

from dataclasses import dataclass
from typing import List

@dataclass
class LiDARScan:
    """Represents a LiDAR scan."""
    points: np.ndarray      # Shape: (N, 3) for x, y, z
    intensities: np.ndarray # Shape: (N,) reflectivity values
    timestamp: float

    def filter_by_range(self, min_range: float, max_range: float) -> 'LiDARScan':
        """Filter points by distance from sensor."""
        distances = np.linalg.norm(self.points, axis=1)
        mask = (distances >= min_range) & (distances <= max_range)
        return LiDARScan(
            points=self.points[mask],
            intensities=self.intensities[mask],
            timestamp=self.timestamp
        )

    def remove_ground_plane(self, height_threshold: float = 0.2) -> 'LiDARScan':
        """Simple ground plane removal based on height."""
        mask = self.points[:, 2] > height_threshold
        return LiDARScan(
            points=self.points[mask],
            intensities=self.intensities[mask],
            timestamp=self.timestamp
        )

def get_pose(self) -> dict:
        """Get current pose estimate."""
        return {
            "position": self.position.tolist(),
            "orientation": self.orientation.as_quat().tolist(),
            "velocity": self.velocity.tolist()
        }

Raw IMU integration suffers from drift over time due to sensor noise and bias. In practice, IMU data must be fused with other sensors (camera, LiDAR, GPS) for accurate long-term pose estimation.

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, Dict

@dataclass
class Observation:
    """Sensory observation from the environment."""
    visual: np.ndarray       # Camera image
    proprioception: Dict[str, float]  # Joint positions
    tactile: np.ndarray      # Touch sensors
    timestamp: float

@dataclass
class Action:
    """Motor command to execute."""
    joint_velocities: Dict[str, float]
    gripper_position: float

class EmbodiedAgent(ABC):
    """Base class for embodied intelligent agents."""

    def __init__(self):
        self.internal_state: Dict[str, Any] = {}
        self.memory: list = []

    @abstractmethod
    def perceive(self, observation: Observation) -> Dict[str, Any]:
        """Process sensory input into internal representation."""
        pass

    @abstractmethod
    def decide(self, perception: Dict[str, Any]) -> Action:
        """Decide on an action based on perception."""
        pass

    @abstractmethod
    def learn(self, observation: Observation, action: Action,
              result: Observation) -> None:
        """Learn from the outcome of an action."""
        pass

    def step(self, observation: Observation) -> Action:
        """Execute one sensorimotor cycle."""
        # Perceive
        perception = self.perceive(observation)

Embodied agents don't passively receive information—they actively seek it out:

class ActivePerceptionAgent(EmbodiedAgent):
    """Agent that actively gathers information."""

    def __init__(self, curiosity_weight: float = 0.3):
        super().__init__()
        self.curiosity_weight = curiosity_weight
        self.visited_regions = set()

    def compute_information_gain(self, position: tuple) -> float:
        """Estimate information gain from moving to a position."""
        # Higher gain for unexplored regions
        if position in self.visited_regions:
            return 0.1  # Low gain for known areas
        return 1.0  # High gain for unknown areas

    def decide(self, perception: Dict[str, Any]) -> Action:
        """Balance task completion with exploration."""
        task_action = self._compute_task_action(perception)
        explore_action = self._compute_explore_action(perception)

        # Weight between task and exploration
        if np.random.random() < self.curiosity_weight:
            return explore_action
        return task_action

    def _compute_task_action(self, perception: Dict[str, Any]) -> Action:
        """Compute action for main task."""
        # Placeholder - would use task-specific logic
        return Action(joint_velocities={}, gripper_position=0.0)

def _compute_explore_action(self, perception: Dict[str, Any]) -> Action:
        """Compute action to explore unknown areas."""
        # Placeholder - would move toward high information gain
        return Action(joint_velocities={}, gripper_position=0.0)

Human-like hands enable use of human tools:

from dataclasses import dataclass
from typing import List, Optional
from enum import Enum

class GripType(Enum):
    POWER = "power"      # Full hand grip
    PRECISION = "precision"  # Fingertip grip
    LATERAL = "lateral"   # Side pinch
    HOOK = "hook"        # Finger hook

@dataclass
class AnthropomorphicHand:
    """Model of a human-like robot hand."""
    num_fingers: int = 5
    thumb_opposition: bool = True
    finger_segments: int = 3

    def available_grips(self) -> List[GripType]:
        """Return grip types available with this hand design."""
        grips = [GripType.HOOK]  # Always available

        if self.num_fingers >= 4:
            grips.append(GripType.POWER)

        if self.thumb_opposition:
            grips.append(GripType.PRECISION)
            grips.append(GripType.LATERAL)

        return grips

    def select_grip_for_object(self, object_diameter_cm: float,
                                object_weight_kg: float) -> Optional[GripType]:
        """Select appropriate grip for an object."""
        if object_weight_kg > 2.0:
            return GripType.POWER
        elif object_diameter_cm < 2.0:
            return GripType.PRECISION
        elif object_diameter_cm < 5.0:
            return GripType.LATERAL
        else:
            return GripType.POWER

from rclpy.node import Node
from sensor_msgs.msg import JointState

# Soft limits in radians (lower, upper)
LIMITS = {'l_knee': (0.0, 0.75), 'r_knee': (0.0, 0.75)}

class JointMonitor(Node):
    def __init__(self):
        super().__init__('joint_monitor')
        self.subscription = self.create_subscription(
            JointState, 'joint_states', self.on_joint_state, 10)

    def on_joint_state(self, msg: JointState):
        for name, position in zip(msg.name, msg.position):
            if name not in LIMITS:
                continue
            low, high = LIMITS[name]
            if not low <= position <= high:
                self.get_logger().warn(
                    f'{name} at {position:.3f} rad outside [{low}, {high}]',
                    throttle_duration_sec=1.0)

def main():
    rclpy.init()
    rclpy.spin(JointMonitor())

