Two effects break many humanoid controllers on first contact with hardware: actuators that cannot deliver the commanded torque, and delays** between sensing and acting. Both are cheap to model.

from collections import deque

class ActuatorModel:
    """PD position actuator with torque saturation and a torque-speed limit."""

    def __init__(self, kp, kd, tau_max, vel_max):
        self.kp, self.kd = kp, kd
        self.tau_max, self.vel_max = tau_max, vel_max

    def torque(self, q_des, q, qd):
        tau = self.kp  (q_des - q) - self.kd  qd
        # Available torque falls linearly to zero at maximum speed
        available = self.tau_max * max(0.0, 1.0 - abs(qd) / self.vel_max)
        return float(np.clip(tau, -available, available))

class LatencyBuffer:
    """Delays actions by a whole number of control steps."""

    def __init__(self, delay_steps: int, default_action):
        self.buffer = deque([default_action] * delay_steps, maxlen=delay_steps + 1)

    def step(self, action):
        self.buffer.append(action)
        return self.buffer.popleft()

The simplest approach treats actions like words. Each continuous action dimension is clipped to a range and split into a fixed number of bins. RT-1 and RT-2 used 256 bins per dimension. The model then predicts one token per dimension with an ordinary cross-entropy loss, exactly like next-word prediction.


class ActionTokenizer:
    """Map continuous actions to integer bins and back."""

    def __init__(self, low: np.ndarray, high: np.ndarray, n_bins: int = 256):
        self.low, self.high, self.n_bins = low, high, n_bins

    def encode(self, action: np.ndarray) -> np.ndarray:
        clipped = np.clip(action, self.low, self.high)
        norm = (clipped - self.low) / (self.high - self.low)      # 0..1
        return np.minimum((norm * self.n_bins).astype(int), self.n_bins - 1)

    def decode(self, tokens: np.ndarray) -> np.ndarray:
        centers = (tokens + 0.5) / self.n_bins                   # bin centers
        return self.low + centers * (self.high - self.low)

tok = ActionTokenizer(low=np.full(7, -1.0), high=np.full(7, 1.0))
a = np.array([0.10, -0.25, 0.0, 0.0, 0.05, 0.0, 1.0])
print(tok.encode(a))              # seven integers in [0, 255]
print(tok.decode(tok.encode(a)))  # close to a, with quantization error

SYSTEM_PROMPT = (
    "You convert spoken robot instructions into JSON matching this schema:\n"
    + json.dumps(RobotCommand.model_json_schema())
    + "\nAllowed actions: navigate_to, pick, place, look_at, stop. "
    "If the request is ambiguous or unsupported, set needs_clarification=true "
    "and ask one short question. Output JSON only."
)

def parse_intent(llm: LLMClient, transcript: str) -> RobotCommand | None:
    raw = llm.complete(SYSTEM_PROMPT, transcript)
    try:
        return RobotCommand.model_validate_json(raw)
    except ValidationError:
        return None      # caller asks the user to rephrase

An LLM may return an action name that is not in the schema, or valid JSON with nonsensical values. The `Literal` type rejects unknown actions at parse time; the whitelist in the safety gate is a second, independent check.

def handle_utterance(self, audio):
        text = self.stt.transcribe(audio, 16_000).strip().lower()
        if "stop" in text.split():                 # fast path, no LLM
            return self.cancel_all()
        if self.pending is not None:
            return self.resolve_confirmation(text)
        cmd = parse_intent(self.llm, text)
        if cmd is None or cmd.needs_clarification:
            return self.speak((cmd and cmd.clarification_question) or "Please rephrase.")
        if cmd.action not in ALLOWED_ACTIONS:
            return self.speak(f"I am not allowed to {cmd.action}.")
        if cmd.confidence < 0.6:
            return self.speak("I'm not sure I understood. Please repeat.")
        if cmd.action == "pick" and cmd.target is None:
            return self.speak("What should I pick up?")
        if cmd.action in CONFIRM_REQUIRED:
            self.pending = cmd
            return self.speak(f"Do you want me to {cmd.action} the {cmd.target.category}? Say yes or no.")
        self.execute(cmd)

    def resolve_confirmation(self, text: str):
        cmd, self.pending = self.pending, None
        if text in ("yes", "yes please", "confirm"):
            return self.execute(cmd)
        self.speak("Cancelled.")

def execute(self, cmd):
        if cmd.action == "navigate_to":
            if cmd.location not in NAMED_PLACES:
                return self.speak("I don't know that place.")
            goal = NavigateToPose.Goal()
            goal.pose = PoseStamped()
            goal.pose.header.frame_id = "map"
            goal.pose.header.stamp = self.get_clock().now().to_msg()
            goal.pose.pose.position.x, goal.pose.pose.position.y = NAMED_PLACES[cmd.location]
            goal.pose.pose.orientation.w = 1.0
            self.send(self.nav, goal)
        elif cmd.action == "pick":
            # grounder wraps ground_object() and a tf2 transform to base_link
            point, err = self.grounder.locate(cmd.target)
            if err:
                return self.speak(err)
            goal = PickObject.Goal()
            goal.object_label = cmd.target.category
            goal.target.header.frame_id = "base_link"
            goal.target.point.x, goal.target.point.y, goal.target.point.z = map(float, point)
            self.send(self.pick, goal)

    def send(self, client, goal):
        if not client.wait_for_server(timeout_sec=2.0):
            return self.speak("That skill is not available right now.")
        future = client.send_goal_async(goal)
        future.add_done_callback(self.on_goal_response)

def on_goal_response(self, future):
        handle = future.result()
        if not handle.accepted:
            return self.speak("The robot rejected that goal.")
        self.active_goals.append(handle)
        handle.get_result_async().add_done_callback(
            lambda f: self.speak("Done." if f.result().status == 4 else "That did not succeed."))

    def cancel_all(self):
        for handle in self.active_goals:
            handle.cancel_goal_async()
        self.active_goals.clear()
        self.pending = None
        self.speak("Stopping.")

Status value 4 is `GoalStatus.STATUS_SUCCEEDED` from `action_msgs`; import the constant in production code instead of using the literal. A `main()` function would create the node with concrete STT, LLM, and grounder objects and run a microphone thread that calls `handle_utterance` whenever voice activity ends.

A skill is a tested, parameterized behavior with explicit preconditions and effects. The library is the planner's entire vocabulary.

from dataclasses import dataclass, field
from typing import Callable

@dataclass
class WorldState:
    robot_at: str = "charging_dock"
    holding: str | None = None
    object_locations: dict[str, str] = field(default_factory=dict)
    known_places: set[str] = field(default_factory=set)

@dataclass
class Skill:
    name: str
    description: str
    params: dict[str, str]                                # param name -> type description
    precondition: Callable[[WorldState, dict], str | None]  # None if OK, else reason
    effect: Callable[[WorldState, dict], None]            # symbolic update for dry-runs

def pre_navigate(s, a):
    return None if a["place"] in s.known_places else f"unknown place {a['place']}"

def pre_pick(s, a):
    if s.holding:
        return f"already holding {s.holding}"
    if s.object_locations.get(a["object"]) != s.robot_at:
        return f"{a['object']} is not at {s.robot_at}"
    return None

def pre_place(s, a):
    return None if s.holding == a["object"] else f"not holding {a['object']}"

A robotics prompt has three jobs: describe the available skills precisely, fix the output format, and show examples of good behavior, including refusing or asking when unsure.


def build_system_prompt(skills: dict, state: WorldState) -> str:
    skill_docs = "\n".join(
        f"- {s.name}({', '.join(f'{k}: {v}' for k, v in s.params.items())}): {s.description}"
        for s in skills.values()
    )
    return (
        "You are the task planner for a humanoid robot. You may ONLY use these skills:\n"
        f"{skill_docs}\n\n"
        f"Current world state:\n{json.dumps(state.__dict__, default=list, indent=2)}\n\n"
        "Rules: use only listed skills and known places/objects; never invent objects; "
        "if the request is unsafe, impossible, or ambiguous, return a plan with a single "
        "ask_human step. Respond with JSON only."
    )

from pydantic import BaseModel, Field

class PlanStep(BaseModel):
    skill: str
    args: dict[str, str] = Field(default_factory=dict)

class Plan(BaseModel):
    reasoning: str = Field(description="One or two sentences explaining the plan")
    steps: list[PlanStep] = Field(min_length=1, max_length=12)

OUTPUT_INSTRUCTIONS = "Output must validate against:\n" + json.dumps(Plan.model_json_schema())

def validate_plan(raw: str, state: WorldState, simulator=None) -> tuple[Plan | None, str | None]:
    # 1. Schema check
    try:
        plan = Plan.model_validate_json(raw)
    except ValidationError as e:
        return None, f"invalid JSON plan: {e.errors()[0]['msg']}"
    # 2. Symbolic precondition check on a copy of the world state
    sim_state = copy.deepcopy(state)
    for i, step in enumerate(plan.steps):
        skill = SKILLS.get(step.skill)
        if skill is None:
            return None, f"step {i}: unknown skill '{step.skill}'"
        if set(step.args) != set(skill.params):
            return None, f"step {i}: expected args {sorted(skill.params)}"
        reason = skill.precondition(sim_state, step.args)
        if reason:
            return None, f"step {i} ({step.skill}): {reason}"
        skill.effect(sim_state, step.args)
    # 3. Optional physics dry-run in Gazebo / Isaac Sim
    if simulator is not None:
        ok, detail = simulator.dry_run(plan)
        if not ok:
            return None, f"simulation dry-run failed: {detail}"
    return plan, None

The symbolic check catches most LLM mistakes, such as picking an object the robot is not next to, in microseconds. The physics dry-run catches problems the symbolic model cannot see, such as an unreachable shelf, but costs seconds to minutes.
